INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Inkrement bei /26 gleich 64?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-26) = 64"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schrittweite hat /24 mit /27?', 3, '[{"text": "32", "correct": true, "because": "2^(32-27) = 32"}, {"text": "64", "correct": false, "because": "Für /26"}, {"text": "16", "correct": false, "because": "Für /28"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Inkrement bei /28 ist 16. b) Die Schrittweite hängt von Hostbits ab.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2^(32-28) = 16, b) Hostbits bestimmen"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Inkrement-Berechnung?', 4, '[{"text": "Hostbits", "correct": false, "because": "Bestimmen die Schrittweite"}, {"text": "Formel 2^(32-m)", "correct": false, "because": "Grundlage der Berechnung"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /30 ein Inkrement von 4 hat?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-30) = 4"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Inkrement hat /25?', 3, '[{"text": "128", "correct": true, "because": "2^(32-25) = 128"}, {"text": "64", "correct": false, "because": "Für /26"}, {"text": "256", "correct": false, "because": "Für /24"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen das Inkrement?', 5, '[{"text": "Anzahl Hostbits", "correct": true, "because": "2^(32-m)"}, {"text": "Netzwerkmaske", "correct": true, "because": "Definiert m"}, {"text": "Protokolltyp", "correct": false, "because": "Irrelevant"}, {"text": "Bandbreite", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /29 hat ein Inkrement von 8. b) Das Inkrement zählt nur Netzwerkbits. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(32-29) = 8, b) falsch, Hostbits zählen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Schrittweite?', 4, '[{"text": "Netzwerkmaske", "correct": false, "because": "Bestimmt Hostbits"}, {"text": "Exponentiation", "correct": false, "because": "Formel 2^(32-m)"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Inkrement bei /16 gleich 65.536?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-16) = 65.536"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Inkrement hat /20?', 4, '[{"text": "4.096", "correct": true, "because": "2^(32-20) = 4.096"}, {"text": "2.048", "correct": false, "because": "Für /21"}, {"text": "8.192", "correct": false, "because": "Für /19"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /32 ein Inkrement von 0 hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "2^(32-32) = 1"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Inkrement-Berechnung?', 3, '[{"text": "Hostbits", "correct": true, "because": "Bestimmen die Schrittweite"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /27 hat ein Inkrement von 32. b) Das Inkrement ist immer 256.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(32-27) = 32, b) variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schrittweiten passen zu diesen Masken?', 5, '[{"text": "/26 = 64", "correct": true, "because": "2^(32-26) = 64"}, {"text": "/30 = 4", "correct": true, "because": "2^(32-30) = 4"}, {"text": "/24 = 128", "correct": false, "because": "/24 = 256"}, {"text": "/28 = 32", "correct": false, "because": "/28 = 16"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Schrittweite unwichtig?', 3, '[{"text": "Hostbits", "correct": false, "because": "Bestimmen Inkrement"}, {"text": "Netzwerkmaske", "correct": false, "because": "Definiert m"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /18 ein Inkrement von 16.384?', 3, '[{"text": "Ja", "correct": true, "because": "2^(32-18) = 16.384"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /31 ein Inkrement von 2 hat?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-31) = 2"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Inkrement hat /22?', 4, '[{"text": "1.024", "correct": true, "because": "2^(32-22) = 1.024"}, {"text": "512", "correct": false, "because": "Für /23"}, {"text": "2.048", "correct": false, "because": "Für /21"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske hat ein Inkrement von 8?', 3, '[{"text": "/29", "correct": true, "because": "2^(32-29) = 8"}, {"text": "/28", "correct": false, "because": "Inkrement 16"}, {"text": "/30", "correct": false, "because": "Inkrement 4"}]');
